use serde_json::Value;

/// 安全提取 i64：兼顾整数、浮点数、整数字符串及小数数字符串 ("10" / "10.00")
pub fn get_i64(val: &Value, key: &str) -> i64 {
    val.get(key)
        .and_then(|v| match v {
            Value::Number(n) => n.as_i64().or_else(|| n.as_f64().map(|f| f as i64)),
            Value::String(s) => s
                .parse::<i64>()
                .ok()
                .or_else(|| s.parse::<f64>().map(|f| f as i64).ok()),
            _ => None,
        })
        .unwrap_or(0)
}

/// 安全提取 f64：兼顾浮点、整型及数字字符串
pub fn get_f64(val: &Value, key: &str) -> f64 {
    val.get(key)
        .and_then(|v| match v {
            Value::Number(n) => n.as_f64(),
            Value::String(s) => s.parse::<f64>().ok(),
            _ => None,
        })
        .unwrap_or(0.0)
}

/// 安全提取 String：将各类标量平滑序列化为文本
pub fn get_str(val: &Value, key: &str) -> String {
    match val.get(key) {
        Some(Value::String(s)) => s.clone(),
        Some(Value::Number(n)) => n.to_string(),
        Some(Value::Bool(b)) => b.to_string(),
        _ => String::new(),
    }
}

/// 安全提取val：
pub fn get_val(val: &Value, key: &str) -> Value {
    match val.get(key) {
        Some(Value::Bool(s)) => s.clone(),
        _ => Value::Null,
    }
}
